window.FILM_WORK_PROMPTS={"work_id":"src-64a0fe7c2ed9cbfc","records":[{"work_id":"src-64a0fe7c2ed9cbfc","frame_id":"FG-9de7983eac0f0caf","source_url":"https://film-grab.com/wp-content/uploads/photo-gallery/thumb/Mahler_04.jpg","source_page":"https://film-grab.com/2025/05/20/mahler/","scene":"白色人形躯体仰面平躺在粗糙的灰褐色岩石地面上，四肢向不同方向伸展，背景是层叠的深色岩石。","analysis":"画面采用俯视角度拍摄，白色人形躯体位于画面中央，全身可见，四肢张开，头部朝向左侧。人物与周围灰褐色岩石形成强烈明暗对比，白色躯体在阴影中显得突出。光线从上方照射，岩石表面纹理清晰，阴影层次丰富，整体色调偏冷。","prompt":"俯视角度，白色人形躯体仰面平躺在粗糙的灰褐色岩石地面上，四肢向不同方向伸展，头部朝向左侧，身体呈舒展姿态。周围是层叠的深色岩石，表面纹理粗糙，有明显的风化痕迹。光线从上方照射，白色躯体与灰褐色岩石形成强烈对比，阴影层次丰富，整体色调偏冷，营造出荒凉、静谧的视觉氛围。","verification":"观图待人工核","selection":"来源画面均匀采样，代表性待人工精选","model":"Qwen3.8-27B-FP8","created":"2026-10-09T12:07:20-07:00","analysis_kind":"模型观图草稿","prompt_kind":"基于源画面的创作改写","instruction_version":"film-still-observation-v2.1-single-hd-conservative","timecode":null,"camera_movement":"静帧无法判定","observed_image_url":"https://film-grab.com/wp-content/uploads/photo-gallery/Mahler_04.jpg","observed_dimensions":[1755,1063],"source_thumbnail_dimensions":[500,303],"source_image_match_mae":0.118,"observed_resolution":"normal","observation_limits":[],"id":"VP-3a59a40499705280","origin":"visual"},{"work_id":"src-64a0fe7c2ed9cbfc","frame_id":"FG-d3d094198a00c8e8","source_url":"https://film-grab.com/wp-content/uploads/photo-gallery/thumb/Mahler_10.jpg","source_page":"https://film-grab.com/2025/05/20/mahler/","scene":"一名穿浅色西装的男子站在昏暗室内窗前，身体侧向右侧，左手撑在窗台上，窗外是开阔的湖面和远处朦胧的山脉。","analysis":"画面采用框式构图，深色木质窗框将人物框在中央。人物上半身及大腿部分可见，呈侧身站立姿态，左手平放支撑在窗台上。室内光线极暗，人物处于逆光剪影状态，仅能辨识浅色西装轮廓。窗外自然光充足，呈现冷调的灰蓝色水面与青灰色远山，明暗对比强烈。","prompt":"昏暗的室内，一名男子站在巨大的木质窗框前，身穿浅色西装外套，身体侧向画面右侧，左手撑在窗台上。人物处于逆光中，面部和身体细节隐没在阴影里，呈现半剪影效果。窗外是开阔平静的湖面，远处有连绵起伏的青色山脉，天空呈现阴天的灰白色。整体色调偏冷，室内深褐色木墙与窗外冷蓝色自然景观形成强烈明暗对比，营造出静谧、沉思的氛围。","verification":"观图待人工核","selection":"来源画面均匀采样，代表性待人工精选","model":"Qwen3.8-27B-FP8","created":"2026-10-09T12:07:27-07:00","analysis_kind":"模型观图草稿","prompt_kind":"基于源画面的创作改写","instruction_version":"film-still-observation-v2.1-single-hd-conservative","timecode":null,"camera_movement":"静帧无法判定","observed_image_url":"https://film-grab.com/wp-content/uploads/photo-gallery/Mahler_10.jpg","observed_dimensions":[1755,1063],"source_thumbnail_dimensions":[500,303],"source_image_match_mae":0.12,"observed_resolution":"normal","observation_limits":[],"id":"VP-e0c9b53b955b4bef","origin":"visual"},{"work_id":"src-64a0fe7c2ed9cbfc","frame_id":"FG-3e7fc9e64ec2e962","source_url":"https://film-grab.com/wp-content/uploads/photo-gallery/thumb/Mahler_17.jpg","source_page":"https://film-grab.com/2025/05/20/mahler/","scene":"六个人物站在湖边碎石坡上，背景是宽阔的湖面、远处的岛屿和朦胧的山脉，左侧有茂密的绿色树木。","analysis":"画面采用广角视野，人物位于画面中下部，呈一字排开站立在倾斜的碎石坡上。人物全身可见，身形在广阔的自然环境中显得较小。光线柔和均匀，整体色调偏冷，以蓝灰色为主，天空与远山呈现出明显的空气透视效果，层次分明。","prompt":"这是一张写实风格的户外场景图。画面主体是六个人物，他们站在一片倾斜的灰白色碎石坡上，背景是宽阔平静的深蓝色湖面。人物大多赤裸上身，穿着简单的短裤或围裙，姿态各异，有的站立，有的微微前倾，似乎在交谈或摆姿势。画面左侧是一棵巨大的深绿色针叶树，占据了约三分之一的画面宽度。远处湖面上有一个覆盖着植被的小岛，背景是层峦叠嶂的山脉，在雾气中呈现出深浅不一的蓝灰色调。整体光线柔和，色彩饱和度较低，营造出一种宁静而略带忧郁的氛围。","verification":"观图待人工核","selection":"来源画面均匀采样，代表性待人工精选","model":"Qwen3.8-27B-FP8","created":"2026-10-09T12:07:34-07:00","analysis_kind":"模型观图草稿","prompt_kind":"基于源画面的创作改写","instruction_version":"film-still-observation-v2.1-single-hd-conservative","timecode":null,"camera_movement":"静帧无法判定","observed_image_url":"https://film-grab.com/wp-content/uploads/photo-gallery/Mahler_17.jpg","observed_dimensions":[1755,1063],"source_thumbnail_dimensions":[500,303],"source_image_match_mae":0.131,"observed_resolution":"normal","observation_limits":[],"id":"VP-0abf54f9d860c276","origin":"visual"},{"work_id":"src-64a0fe7c2ed9cbfc","frame_id":"FG-1f609f90e1c226b9","source_url":"https://film-grab.com/wp-content/uploads/photo-gallery/thumb/Mahler_24.jpg","source_page":"https://film-grab.com/2025/05/20/mahler/","scene":"一只狐狸头部与颈部特写，嘴巴大张露出牙齿与舌头，周围环绕着暗色的蕨类植物枝叶，背景几乎完全隐没在黑暗中。","analysis":"画面主体为狐狸的头部和颈部，身体其余部分不可见。狐狸呈侧面姿态，嘴部张开，可见上下牙齿和粉红色的舌头。构图紧凑，主体占据画面中心偏左位置。光线极暗，仅有微弱的光线勾勒出狐狸毛发的轮廓和面部特征，整体呈现低照度、高对比度的视觉效果，色彩以深灰、暗褐为主，局部有冷色调反光。","prompt":"一只狐狸的头部和颈部特写，侧面视角，嘴巴大张露出尖锐的牙齿和粉红色舌头，眼睛半睁，耳朵竖立。狐狸毛发呈灰褐色，在微弱光线下显现出细腻的质感。周围环绕着暗色的蕨类植物枝叶，背景几乎完全黑暗，仅有极微弱的光线照亮狐狸面部和颈部，营造出神秘、紧张的氛围。画面整体色调偏冷，以深灰、暗褐为主，局部有冷色调反光，低照度摄影风格，细节丰富，质感真实。","verification":"观图待人工核","selection":"来源画面均匀采样，代表性待人工精选","model":"Qwen3.8-27B-FP8","created":"2026-10-09T12:07:42-07:00","analysis_kind":"模型观图草稿","prompt_kind":"基于源画面的创作改写","instruction_version":"film-still-observation-v2.1-single-hd-conservative","timecode":null,"camera_movement":"静帧无法判定","observed_image_url":"https://film-grab.com/wp-content/uploads/photo-gallery/Mahler_24.jpg","observed_dimensions":[1755,1063],"source_thumbnail_dimensions":[500,303],"source_image_match_mae":0.095,"observed_resolution":"normal","observation_limits":[],"id":"VP-ad0278c6c858d378","origin":"visual"},{"work_id":"src-64a0fe7c2ed9cbfc","frame_id":"FG-63d08d25d03e7391","source_url":"https://film-grab.com/wp-content/uploads/photo-gallery/thumb/Mahler_30.jpg","source_page":"https://film-grab.com/2025/05/20/mahler/","scene":"墓地中，两名穿深色制服抬着红棕色棺材，一名穿黑衣红裙的人物站在棺材顶，单臂高举，周围是密集墓碑与黄绿树木。","analysis":"画面采用框式构图，前景枝叶形成天然画框。主体人物全身可见，站立于棺材上方，身形在画面中占比显著。抬棺者仅上半身可见，位于画面下方。背景墓碑层层递远，景深较大。光线柔和，左侧树冠呈金黄色，右侧树叶为深绿色，明暗对比自然，色彩层次丰富。","prompt":"墓地场景，前景左右两侧有茂密枝叶形成框景，左侧树叶呈金黄色，右侧为深绿色。画面中央，两名穿深色制服戴大檐帽的男子抬着一具红棕色木质棺材，棺材上有金色装饰。棺材顶站立一名人物，全身可见，穿黑色上衣与短裙，系红色腰带，穿黑色长靴，头戴深色帽子，右臂高举过头顶。背景是起伏的墓地山坡，密布各式灰色墓碑与十字架，远处有模糊人影。光线柔和，色彩自然，具有胶片质感。","verification":"观图待人工核","selection":"来源画面均匀采样，代表性待人工精选","model":"Qwen3.8-27B-FP8","created":"2026-10-09T12:07:50-07:00","analysis_kind":"模型观图草稿","prompt_kind":"基于源画面的创作改写","instruction_version":"film-still-observation-v2.1-single-hd-conservative","timecode":null,"camera_movement":"静帧无法判定","observed_image_url":"https://film-grab.com/wp-content/uploads/photo-gallery/Mahler_30.jpg","observed_dimensions":[1755,1063],"source_thumbnail_dimensions":[500,303],"source_image_match_mae":0.189,"observed_resolution":"normal","observation_limits":[],"id":"VP-2ccd730c9c15fdcb","origin":"visual"},{"work_id":"src-64a0fe7c2ed9cbfc","frame_id":"FG-3d5958f44d672dc1","source_url":"https://film-grab.com/wp-content/uploads/photo-gallery/thumb/Mahler_03.jpg","source_page":"https://film-grab.com/2025/05/20/mahler/","scene":"一名卷发人物站立于画面中央，双臂向两侧平举张开，身着深色高领衣物。前景被大面积模糊的橙红色亮区占据，背景是灰暗朦胧的山峦轮廓。","analysis":"人物位于画面正中，头部与肩部清晰可见，身体下半部分被前景的橙红色模糊色块遮挡。人物双臂向两侧伸展，手部轮廓可见。背景为低对比度的灰绿色山体，天空呈灰白色。前景的橙红色亮区占据了画面下方约三分之一，呈现出失焦的虚化效果，与清晰的人物形成虚实对比。整体光线柔和，色彩以冷灰背景与暖橙前景形成反差。","prompt":"一名卷发人物站立于画面中央，面部表情平静，双臂向两侧平举张开，手指自然伸展。人物身着深色高领衣物，领口竖起。前景下方被大面积模糊的橙红色亮区占据，呈现出强烈的虚化效果，遮挡了人物腰部以下。背景是灰暗朦胧的山峦轮廓，天空呈灰白色，整体氛围阴沉。画面采用中心构图，人物清晰而前景虚化，形成明显的景深对比。色彩上，背景的冷灰绿色与前景的暖橙色形成鲜明反差，光线柔和均匀，无强烈阴影。","verification":"观图待人工核","selection":"来源画面均匀采样，代表性待人工精选","model":"Qwen3.8-27B-FP8","created":"2026-10-11T16:46:22+08:00","analysis_kind":"模型观图草稿","prompt_kind":"基于源画面的创作改写","instruction_version":"film-still-observation-v2.1-single-hd-conservative","timecode":null,"camera_movement":"静帧无法判定","observed_image_url":"https://film-grab.com/wp-content/uploads/photo-gallery/Mahler_03.jpg","observed_dimensions":[1755,1063],"source_thumbnail_dimensions":[500,303],"source_image_match_mae":0.128,"observed_resolution":"normal","observation_limits":[],"id":"VP-b4bae29bd684c58a","origin":"visual"},{"work_id":"src-64a0fe7c2ed9cbfc","frame_id":"FG-c8fca58236d3a622","source_url":"https://film-grab.com/wp-content/uploads/photo-gallery/thumb/Mahler_11.jpg","source_page":"https://film-grab.com/2025/05/20/mahler/","scene":"金发女性上半身正面特写，面部大部分处于阴影中，背景为模糊的蓝灰色调，似为水面或天空。","analysis":"画面主体为女性面部及肩部，占据画面中心。采用侧光照明，人物左脸（画面右侧）受光，右脸（画面左侧）陷入深重阴影，形成强烈的明暗对比。背景虚化严重，呈冷色调蓝灰，与人物暖色皮肤形成冷暖对比。人物视线直视前方，神情凝重。","prompt":"一位金发女性的正面特写，她身穿浅色高领针织衫，长发垂在肩头。面部大部分笼罩在阴影中，只有右半边脸（画面左侧）被柔和的侧光照亮，显露出苍白的皮肤和深邃的眼睛。背景是模糊的蓝灰色，像是阴天或黄昏时的水面或天空，营造出一种阴郁、神秘的氛围。光线从右侧打来，在面部形成强烈的明暗对比，突出了人物的轮廓和表情。","verification":"观图待人工核","selection":"来源画面均匀采样，代表性待人工精选","model":"Qwen3.8-27B-FP8","created":"2026-10-11T16:46:30+08:00","analysis_kind":"模型观图草稿","prompt_kind":"基于源画面的创作改写","instruction_version":"film-still-observation-v2.1-single-hd-conservative","timecode":null,"camera_movement":"静帧无法判定","observed_image_url":"https://film-grab.com/wp-content/uploads/photo-gallery/Mahler_11.jpg","observed_dimensions":[1755,1063],"source_thumbnail_dimensions":[500,303],"source_image_match_mae":0.119,"observed_resolution":"normal","observation_limits":[],"id":"VP-77b021b76a2512c8","origin":"visual"},{"work_id":"src-64a0fe7c2ed9cbfc","frame_id":"FG-4a623adbaec3299a","source_url":"https://film-grab.com/wp-content/uploads/photo-gallery/thumb/Mahler_18.jpg","source_page":"https://film-grab.com/2025/05/20/mahler/","scene":"湖岸岩石上，左侧赤裸上身少年与右侧戴草帽男子相对而坐，右下角有明亮火焰，背景为宽阔湖面与连绵青山。","analysis":"画面采用横向构图，人物位于中景偏左，右下角火焰占据显著位置。左侧少年全身可见，呈蜷缩坐姿；右侧男子全身可见，戴草帽，身体微侧。背景山脉与湖面占据画面上半部，天空呈现淡粉色调。光线柔和，火焰的暖橙色与周围冷色调岩石形成对比，人物面部受光均匀，阴影柔和。","prompt":"湖岸岩石场景，左侧一名赤裸上身、穿浅色短裤的少年蜷腿而坐，双手抱膝，赤脚踩在岩石上；右侧一名戴草帽、穿深色旧衣的男子盘腿而坐，脚穿草鞋，手中持物。右下角前景处有明亮的橙黄色火焰燃烧。背景是平静的宽阔湖面，远处连绵起伏的绿色山峦，天空呈现淡粉紫色调。岩石表面粗糙，带有青苔痕迹，整体光线柔和，色彩自然。","verification":"观图待人工核","selection":"来源画面均匀采样，代表性待人工精选","model":"Qwen3.8-27B-FP8","created":"2026-10-11T16:46:42+08:00","analysis_kind":"模型观图草稿","prompt_kind":"基于源画面的创作改写","instruction_version":"film-still-observation-v2.1-single-hd-conservative","timecode":null,"camera_movement":"静帧无法判定","observed_image_url":"https://film-grab.com/wp-content/uploads/photo-gallery/Mahler_18.jpg","observed_dimensions":[1755,1063],"source_thumbnail_dimensions":[500,303],"source_image_match_mae":0.184,"observed_resolution":"normal","observation_limits":[],"id":"VP-d5f475ee80f6e7c8","origin":"visual"},{"work_id":"src-64a0fe7c2ed9cbfc","frame_id":"FG-ba4c5011017ff562","source_url":"https://film-grab.com/wp-content/uploads/photo-gallery/thumb/Mahler_23.jpg","source_page":"https://film-grab.com/2025/05/20/mahler/","scene":"幽暗森林深处，一名戴帽人物站立于蕨类植物间，周围是密集高耸的深色树干，地面为泥土小径，整体环境极度昏暗。","analysis":"画面采用垂直线条构图，右侧粗大树干占据前景，左侧及背景为密集树林。人物位于画面中左部，全身可见，身形较小，呈站立姿态。光线极弱，仅顶部树冠处有微弱天光透入，整体色调为深黑与暗绿，人物轮廓在暗部中依稀可辨，明暗对比极低，营造出压抑、神秘的视觉氛围。","prompt":"这是一张极度昏暗的森林场景图。画面右侧前景矗立着一根粗壮的深色树干，纹理在阴影中若隐若现。中景左侧，一名头戴帽子的人物站立在茂密的蕨类植物丛中，身穿深色长衣，全身轮廓在黑暗中依稀可见，身形相对于高大的树木显得渺小。背景是无数垂直排列的细长树干，延伸至画面深处。地面是泥土小径，覆盖着低矮植被。整体光线极暗，仅顶部树冠缝隙透出微弱冷光，色调以深黑和暗绿为主，营造出压抑、静谧且神秘的森林氛围。","verification":"观图待人工核","selection":"来源画面均匀采样，代表性待人工精选","model":"Qwen3.8-27B-FP8","created":"2026-10-11T16:46:53+08:00","analysis_kind":"模型观图草稿","prompt_kind":"基于源画面的创作改写","instruction_version":"film-still-observation-v2.1-single-hd-conservative","timecode":null,"camera_movement":"静帧无法判定","observed_image_url":"https://film-grab.com/wp-content/uploads/photo-gallery/Mahler_23.jpg","observed_dimensions":[1755,1063],"source_thumbnail_dimensions":[500,303],"source_image_match_mae":0.091,"observed_resolution":"normal","observation_limits":[],"id":"VP-269c804823071890","origin":"visual"},{"work_id":"src-64a0fe7c2ed9cbfc","frame_id":"FG-84637085362e501e","source_url":"https://film-grab.com/wp-content/uploads/photo-gallery/thumb/Mahler_31.jpg","source_page":"https://film-grab.com/2025/05/20/mahler/","scene":"一名身穿黑色衣物与红色布料的人物蜷缩坐于深色物体上，背景为淡蓝灰色天空，两侧有黑色垂直结构。","analysis":"人物位于画面中央，呈蜷缩坐姿，双腿弯曲，头部低垂，面部被黑色物质覆盖。人物穿着黑色长靴，腿部有黑色长袜，身上缠绕红色布料。背景为均匀的淡蓝灰色天空，两侧有黑色垂直结构，形成框架式构图。光线从上方照射，人物背部和腿部有高光，整体色调偏冷，红色布料在暗色背景中形成强烈对比。","prompt":"一名人物蜷缩坐于深色物体上，双腿弯曲，头部低垂，面部被黑色物质覆盖。人物穿着黑色长靴，腿部有黑色长袜，身上缠绕红色布料。背景为均匀的淡蓝灰色天空，两侧有黑色垂直结构，形成框架式构图。光线从上方照射，人物背部和腿部有高光，整体色调偏冷，红色布料在暗色背景中形成强烈对比。","verification":"观图待人工核","selection":"来源画面均匀采样，代表性待人工精选","model":"Qwen3.8-27B-FP8","created":"2026-10-11T16:47:02+08:00","analysis_kind":"模型观图草稿","prompt_kind":"基于源画面的创作改写","instruction_version":"film-still-observation-v2.1-single-hd-conservative","timecode":null,"camera_movement":"静帧无法判定","observed_image_url":"https://film-grab.com/wp-content/uploads/photo-gallery/Mahler_31.jpg","observed_dimensions":[1755,1063],"source_thumbnail_dimensions":[500,303],"source_image_match_mae":0.111,"observed_resolution":"normal","observation_limits":[],"id":"VP-7379fad36d60f876","origin":"visual"}]};